module.code:
MODS.addItem({
  id: 'field_dressing',
  name: 'Courier Field Dressing',
  type: 'consumable',
  purpose: 'use',
  effect: 'heal',
  healAmount: 18,
  stackable: true,
  maxStack: 10,
  value: 14,
  icon: '🩹',
  desc: 'A compact courier dressing that restores 18 condition.',
  acquisition: {
    merchantTables: [
      { id: 'general', qty: 2 },
      { id: 'traveler', qty: 2 }
    ],
    search: true,
    searchWeight: 3
  }
});

MODS.addItem({
  id: 'waxed_route_cord',
  name: 'Waxed Route Cord',
  type: 'material',
  purpose: 'trade',
  effect: 'sell',
  stackable: true,
  maxStack: 20,
  value: 8,
  icon: '🧵',
  desc: 'Waxed cord used by couriers to bind parcels and mark a trail; a trade good worth 8 gold.',
  acquisition: {
    merchantTables: [
      { id: 'general', qty: 2 },
      { id: 'traveler', qty: 3 }
    ],
    search: true,
    searchWeight: 4
  }
});

MODS.addItem({
  id: 'courier_satchel',
  name: 'Weathered Courier Satchel',
  type: 'quest',
  purpose: 'quest',
  stackable: false,
  value: 0,
  icon: '🎒',
  desc: 'A mud-streaked satchel bearing a courier seal. It belongs with its waiting dispatcher.'
});

MODS.addQuestTemplate({
  id: 'recover_courier_satchel',
  title: "The Courier's Trail",
  description: 'A courier vanished between waymarks. Follow the marked trail, recover the sealed satchel, and return it to the dispatcher who sent you.',
  acquisition: {
    structures: ['cabin', 'camp']
  },
  turnInPolicy: {
    type: 'original_giver'
  },
  objectives: [{
    id: 'recover_satchel',
    type: 'recover',
    label: 'Recover the Weathered Courier Satchel',
    item: {
      definitionId: 'yaw_couriers_trail:courier_satchel',
      name: 'Weathered Courier Satchel',
      quantity: 1
    },
    required: 1
  }],
  worldDirectives: [{
    id: 'place_lost_satchel',
    type: 'place',
    content: {
      kind: 'item',
      id: 'yaw_couriers_trail:courier_satchel'
    },
    count: 1,
    distance: {
      min: 3,
      max: 6
    },
    objectiveId: 'recover_satchel',
    locationLabel: "Courier's last waymark"
  }],
  consumeOnTurnIn: ['yaw_couriers_trail:courier_satchel'],
  reward: {
    xp: 24,
    gold: 18
  },
  stageGraph: {
    initialStage: 'offered',
    stages: [{
      id: 'offered',
      label: 'Awaiting departure',
      transitions: [{
        id: 'take_route_slip',
        event: 'accept',
        to: 'following_trail',
        effects: [{
          type: 'log',
          text: 'The dispatcher gives you the courier’s last route slip. Beyond the next waymarks, the trail goes quiet.'
        }]
      }]
    }, {
      id: 'following_trail',
      label: 'Following the courier trail',
      transitions: [{
        id: 'secure_satchel',
        event: 'objective_complete',
        to: 'returning',
        effects: [{
          type: 'log',
          text: 'You lift the weathered satchel from the trail. Its courier seal is scarred but unbroken; the dispatcher will want it back.'
        }]
      }, {
        id: 'trail_failed',
        event: 'fail',
        to: 'failed',
        effects: [{
          type: 'log',
          text: 'The courier’s trail is abandoned, leaving the missing dispatch unresolved.'
        }]
      }]
    }, {
      id: 'returning',
      label: 'Returning to the dispatcher',
      transitions: [{
        id: 'return_satchel',
        event: 'turn_in',
        to: 'delivered',
        effects: [{
          type: 'log',
          text: 'The dispatcher checks the battered seal, then clasps the satchel close. The lost route can finally be accounted for.'
        }]
      }, {
        id: 'return_failed',
        event: 'fail',
        to: 'failed',
        effects: [{
          type: 'log',
          text: 'The recovered dispatch never reaches its waiting keeper.'
        }]
      }]
    }, {
      id: 'delivered',
      label: 'Satchel delivered',
      transitions: []
    }, {
      id: 'failed',
      label: 'Trail abandoned',
      transitions: []
    }]
  }
});
